('7', 'جمعة مع دعاء', 'اللهم إنّي أسألك في هذا اليوم المبارك أن ترزقني وأحبابي فعل الخيرات، وترك المنكرات، وحبّ المساكين، وأن تغفر لنا وترحمنا، وإذا أردت بقومٍ فتنةً فتوفّنا غير مفتونين', 'ببسبسيل', '0', NULL, NULL, '1', '2025-12-09 00:02:01', '2025-12-09 00:03:29', NULL, NULL),
('8', 'تصميم جمعة طيبة', 'اللهم اجعلنا ممن استبشر برحمتك وغُفِر له ذنبه. اللهم اجعل لنا في يوم الجمعة دعاءً لا يُرد ورزقًا لا يُعد. جمعة طيبة ', NULL, '0', NULL, NULL, '1', '2025-12-09 00:03:12', '2025-12-09 00:03:36', NULL, NULL),
('9', 'اختار ولا تحتار', 'اختار ولا تحتار\nنجمع بين خبرة السنين وابتكار الخدمة', NULL, '0', NULL, NULL, '1', '2025-12-09 00:04:53', '2025-12-09 00:04:53', NULL, NULL),
('10', 'حوالاتنا الدولية', 'ع حوالاتنا الدولية هي\nالأسرع', NULL, '0', NULL, NULL, '1', '2025-12-09 00:05:47', '2025-12-09 00:05:47', NULL, NULL),
('11', 'أرسل الأموال بثقة', 'أرسل الأموال بثقة، استلمها بسرعة\nمن اي مكان في العالم', NULL, '0', NULL, NULL, '1', '2025-12-09 00:16:06', '2025-12-09 00:16:06', NULL, NULL),
('12', 'نخلص حاوياتك التجارية ', 'نخلص حاوياتك التجارية\nبأسرع وقت وأنسب تكلفة', NULL, '0', NULL, NULL, '1', '2025-12-09 00:18:15', '2025-12-09 00:18:15', NULL, NULL),
('13', 'ننجز معاملاتك الجمركية', 'ننجز معاملاتك الجمركية\nبأعلى معايير الاحتراف والسرعة', NULL, '0', NULL, NULL, '1', '2025-12-09 00:18:46', '2025-12-09 00:18:46', NULL, NULL);

