-- Structure for `tags`
DROP TABLE IF EXISTS `tags`;
CREATE TABLE IF NOT EXISTS `tags` (
  `id` BIGINT NOT NULL  AUTO_INCREMENT,
  `name` TEXT NOT NULL  ,
  `importance` TEXT NOT NULL DEFAULT 'medium' ,
  `tag_group_id` BIGINT NOT NULL  ,
  `is_repetition` BIGINT NOT NULL DEFAULT '0' ,
  `repetition` TEXT NULL  ,
  `weekly_times` BIGINT NULL  ,
  `monthly_times` BIGINT NULL  ,
  `yearly_times` BIGINT NULL  ,
  `is_there_date_for_sending` BIGINT NOT NULL DEFAULT '0' ,
  `date_for_sending_yearly` DATE NULL  ,
  `weekly_day` TEXT NULL  ,
  `weekly_time` TIME NULL  ,
  `weekly_time_sm` TIME NULL  ,
  `created_at` DATETIME NULL  ,
  `updated_at` DATETIME NULL  ,
  `added_by_user` BIGINT NULL  ,
  `updated_by_user` BIGINT NULL  ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

